// Labelled Seal fixture corpus. Every fixture is generated by code with throwaway Ed25519 keys made at build time
// (nothing secret is checked in). Each carries the verdict `loki verify` must return, so the runner can score accuracy.
import { createHash, createPublicKey, generateKeyPairSync, sign, type KeyObject } from "node:crypto";
import { mkdirSync, rmSync, writeFileSync } from "node:fs";
import { join } from "node:path";
import { canonicalJson, kidOf } from "../../../../src/util/receipt_signer.ts";
import { receiptSha256 } from "../../../../src/engine10/stages/seal.ts";

export type SealLabel = "genuine pass" | "tampered diff" | "missing check" | "deleted sealed copy" | "wrong key" | "unknown-as-pass";
export const SEAL_LABELS: readonly SealLabel[] = ["genuine pass", "tampered diff", "missing check", "deleted sealed copy", "wrong key", "unknown-as-pass"];
export type SealVerdict = "VERIFIED" | "UNSIGNED" | "TAMPERED" | "UNCHECKED";
export interface SealFixture { label: SealLabel; name: string; expected: SealVerdict; build(dir: string): { path: string; pubkey?: KeyObject } }

type Obj = Record<string, unknown>;
const b64u = (b: Buffer | string): string => Buffer.from(b).toString("base64url");
const sha = (s: string): string => createHash("sha256").update(s).digest("hex");
const newKey = (): KeyObject => generateKeyPairSync("ed25519").privateKey;
const pub = (k: KeyObject): KeyObject => createPublicKey(k);
const kidFor = (k: KeyObject): string => kidOf(pub(k));

/** Receipt body as seal writes it: zero stages and the empty-log hash, so no events.jsonl is needed. */
function body(runId: string): Obj {
  return {
    schema: "loki.v10.receipt/1", run_id: runId, task: { source: "text", sha256: "a".repeat(64) }, repo: "o/r",
    base_sha: "b".repeat(40), head_sha: "c".repeat(40), tree: "d".repeat(40), diff_sha256: "e".repeat(64),
    wall: { files: [], passed: true },
    checks: [{ name: "unit", cmd: "bun test", result: "pass", duration_s: 1.2 }, { name: "types", cmd: "tsc --noEmit", result: "pass", duration_s: 2.1 }],
    not_proven: ["full suite"], verdict: "VERIFIED", cost: { usd: 0.1, input_tokens: 100, output_tokens: 20 },
    time: { wall_s: 0, stages: {} }, provider: "claude", model: "claude-x", resumed: false, events_sha256: sha(""),
  };
}
/** Compact EdDSA JWT in the shape signReceipt writes. `headerKid` lets a fixture claim a kid the signing key does not own. */
function jwtFor(key: KeyObject, runId: string, hash: string, headerKid: string = kidFor(key)): string {
  const input = `${b64u(canonicalJson({ alg: "EdDSA", typ: "JWT", kid: headerKid }))}.${b64u(canonicalJson({ job_id: runId, run_id: runId, receipt_sha256: hash, iat: Math.floor(Date.now() / 1000) }))}`;
  return `${input}.${b64u(sign(null, Buffer.from(input), key))}`;
}
interface Opts { pre?: (b: Obj) => void; key?: KeyObject; headerKid?: string; shownKid?: string; mutate?: (r: Obj) => void; rehash?: boolean; wall?: string[] }
/** Seal (hash, optionally sign), then mutate after the seal. `rehash` recomputes receipt_sha256 over the mutation but keeps the old signature. */
function writeReceipt(dir: string, runId: string, o: Opts = {}): string {
  const b = body(runId), runDir = join(dir, "runs", runId);
  mkdirSync(runDir, { recursive: true });
  if (o.wall) {
    mkdirSync(join(runDir, "wall"), { recursive: true });
    b["wall"] = { files: o.wall.map((n) => ({ path: `tests/wall/${n}`, sha256: sha(n + "\n") })), passed: true };
    for (const n of o.wall) writeFileSync(join(runDir, "wall", n), n + "\n");
  }
  o.pre?.(b);
  const hash = receiptSha256(b as never);
  const verification = o.key ? { jwt: jwtFor(o.key, runId, hash, o.headerKid), kid: o.shownKid ?? o.headerKid ?? kidFor(o.key) } : { jwt: null, kid: null };
  const r: Obj = { ...b, receipt_sha256: hash, verification };
  o.mutate?.(r);
  if (o.rehash) { const { receipt_sha256: _h, verification: _v, ...rest } = r; r["receipt_sha256"] = receiptSha256(rest as never); }
  const path = join(runDir, "receipt.json");
  writeFileSync(path, JSON.stringify(r, null, 2) + "\n");
  return path;
}
const setChecks = (r: Obj, f: (c: Obj[]) => Obj[]): void => { r["checks"] = f(r["checks"] as Obj[]); };
const wallCopy = (receiptPath: string, name: string): string => join(receiptPath, "..", "wall", name);

export function sealCorpus(): SealFixture[] {
  const F: SealFixture[] = [];
  const add = (label: SealLabel, name: string, expected: SealVerdict, build: SealFixture["build"]): void => { F.push({ label, name, expected, build }); };

  // genuine pass: sealed, signed, untouched
  add("genuine pass", "signed-two-checks", "VERIFIED", (d) => { const key = newKey(); return { path: writeReceipt(d, "g-1", { key }), pubkey: pub(key) }; });
  add("genuine pass", "signed-with-sealed-wall", "VERIFIED", (d) => { const key = newKey(); return { path: writeReceipt(d, "g-2", { key, wall: ["a.test.ts", "b.test.ts"] }), pubkey: pub(key) }; });
  add("genuine pass", "signed-single-check", "VERIFIED", (d) => { const key = newKey(); return { path: writeReceipt(d, "g-3", { key, pre: (b) => setChecks(b, (c) => c.slice(0, 1)) }), pubkey: pub(key) }; });
  add("genuine pass", "signed-recorded-failure-is-authentic", "VERIFIED", (d) => { const key = newKey(); return { path: writeReceipt(d, "g-4", { key, pre: (b) => { b["verdict"] = "FAILED"; } }), pubkey: pub(key) }; });

  // tampered diff: a field of the sealed receipt changed after the seal
  add("tampered diff", "diff-sha-edited-signed", "TAMPERED", (d) => { const key = newKey(); return { path: writeReceipt(d, "t-1", { key, mutate: (r) => { r["diff_sha256"] = "f".repeat(64); } }), pubkey: pub(key) }; });
  add("tampered diff", "head-sha-edited-unsigned", "TAMPERED", (d) => ({ path: writeReceipt(d, "t-2", { mutate: (r) => { r["head_sha"] = "9".repeat(40); } }) }));
  add("tampered diff", "diff-sha-edited-rehashed-keeps-old-signature", "TAMPERED", (d) => { const key = newKey(); return { path: writeReceipt(d, "t-3", { key, rehash: true, mutate: (r) => { r["diff_sha256"] = "0".repeat(64); } }), pubkey: pub(key) }; });
  add("tampered diff", "verdict-and-diff-edited-signed", "TAMPERED", (d) => { const key = newKey(); return { path: writeReceipt(d, "t-4", { key, mutate: (r) => { r["verdict"] = "FAILED"; r["diff_sha256"] = "1".repeat(64); } }), pubkey: pub(key) }; });

  // missing check: a recorded check removed or rewritten after the seal
  add("missing check", "check-removed-signed", "TAMPERED", (d) => { const key = newKey(); return { path: writeReceipt(d, "m-1", { key, mutate: (r) => setChecks(r, (c) => c.slice(1)) }), pubkey: pub(key) }; });
  add("missing check", "check-removed-rehashed-keeps-old-signature", "TAMPERED", (d) => { const key = newKey(); return { path: writeReceipt(d, "m-2", { key, rehash: true, mutate: (r) => setChecks(r, (c) => c.slice(0, 1)) }), pubkey: pub(key) }; });
  add("missing check", "all-checks-emptied-unsigned", "TAMPERED", (d) => ({ path: writeReceipt(d, "m-3", { mutate: (r) => setChecks(r, () => []) }) }));
  add("missing check", "check-renamed-signed", "TAMPERED", (d) => { const key = newKey(); return { path: writeReceipt(d, "m-4", { key, mutate: (r) => setChecks(r, (c) => c.map((x) => ({ ...x, name: `${String(x["name"])}-renamed` }))) }), pubkey: pub(key) }; });

  // deleted sealed copy: a sealed Wall file removed from (or edited in) the run's wall dir
  add("deleted sealed copy", "one-of-two-deleted-unsigned", "TAMPERED", (d) => { const p = writeReceipt(d, "w-1", { wall: ["a.test.ts", "b.test.ts"] }); rmSync(wallCopy(p, "a.test.ts")); return { path: p }; });
  add("deleted sealed copy", "all-deleted-dir-remains", "TAMPERED", (d) => { const p = writeReceipt(d, "w-2", { wall: ["a.test.ts", "b.test.ts"] }); for (const n of ["a.test.ts", "b.test.ts"]) rmSync(wallCopy(p, n)); return { path: p }; });
  add("deleted sealed copy", "middle-of-three-deleted-signed", "TAMPERED", (d) => { const key = newKey(); const p = writeReceipt(d, "w-3", { key, wall: ["a.test.ts", "b.test.ts", "c.test.ts"] }); rmSync(wallCopy(p, "b.test.ts")); return { path: p, pubkey: pub(key) }; });
  add("deleted sealed copy", "copy-edited-signed", "TAMPERED", (d) => { const key = newKey(); const p = writeReceipt(d, "w-4", { key, wall: ["a.test.ts"] }); writeFileSync(wallCopy(p, "a.test.ts"), "weakened\n"); return { path: p, pubkey: pub(key) }; });

  // wrong key: the signature cannot be tied to the key the verifier trusts
  add("wrong key", "signed-by-A-checked-with-B", "UNCHECKED", (d) => ({ path: writeReceipt(d, "k-1", { key: newKey() }), pubkey: pub(newKey()) }));
  add("wrong key", "signed-by-B-claims-kid-A", "TAMPERED", (d) => { const a = newKey(); return { path: writeReceipt(d, "k-2", { key: newKey(), headerKid: kidFor(a) }), pubkey: pub(a) }; });
  add("wrong key", "display-kid-swapped", "TAMPERED", (d) => { const a = newKey(); return { path: writeReceipt(d, "k-3", { key: a, shownKid: kidFor(newKey()) }), pubkey: pub(a) }; });
  add("wrong key", "signed-by-A-checked-with-C", "UNCHECKED", (d) => ({ path: writeReceipt(d, "k-4", { key: newKey(), wall: ["a.test.ts"] }), pubkey: pub(newKey()) }));

  // unknown-as-pass: a receipt that cannot be established must never read VERIFIED
  add("unknown-as-pass", "unsigned-genuine", "UNSIGNED", (d) => ({ path: writeReceipt(d, "u-1"), pubkey: pub(newKey()) }));
  add("unknown-as-pass", "not-json", "UNCHECKED", (d) => { const p = writeReceipt(d, "u-2"); writeFileSync(p, "{ not json"); return { path: p }; });
  add("unknown-as-pass", "receipt-file-absent", "UNCHECKED", (d) => { const p = writeReceipt(d, "u-3"); rmSync(p); return { path: p }; });
  add("unknown-as-pass", "jwt-not-a-string", "UNCHECKED", (d) => ({ path: writeReceipt(d, "u-4", { mutate: (r) => { r["verification"] = { jwt: 12345, kid: null }; } }) }));
  return F;
}
